//! Real binary integration tests: no mocked CLI, file format or JSON-RPC server.
//! Each run is isolated and uses only files generated by DeckCraft itself.

use std::io::Write;
use std::path::PathBuf;
use std::process::{Command, Output, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};

fn binary() -> &'static str {
    env!("CARGO_BIN_EXE_deckcraft-cli")
}

fn run(args: &[&str]) -> Output {
    Command::new(binary()).args(args).output().expect("start deckcraft-cli")
}

fn successful_json(output: &Output) -> serde_json::Value {
    assert!(output.status.success(), "CLI exited with {:?}: {}", output.status, String::from_utf8_lossy(&output.stderr));
    serde_json::from_slice(&output.stdout).expect("stdout is a JSON document")
}

static NEXT_DIR: AtomicUsize = AtomicUsize::new(0);

struct Scratch(PathBuf);

impl Scratch {
    fn new() -> Self {
        let path = std::env::temp_dir().join(format!("deckcraft-cli-roundtrip-{}-{}", std::process::id(), NEXT_DIR.fetch_add(1, Ordering::Relaxed)));
        std::fs::create_dir(&path).expect("create isolated scratch directory");
        Self(path)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[test]
fn executable_version_and_command_catalogue() {
    let version = run(&["--version"]);
    assert!(version.status.success(), "{}", String::from_utf8_lossy(&version.stderr));
    assert_eq!(String::from_utf8_lossy(&version.stdout).trim(), format!("deckcraft-cli {}", env!("CARGO_PKG_VERSION")));

    let catalogue = successful_json(&run(&["commands", "slide."]));
    let commands = catalogue.as_array().expect("command list");
    assert!(commands.iter().any(|c| c["id"] == "slide.new"));
    assert!(commands.iter().all(|c| c["id"].as_str().is_some_and(|id| id.starts_with("slide."))));
}

#[test]
fn executable_native_pptx_native_roundtrip_preserves_slides() {
    let scratch = Scratch::new();
    let native = scratch.0.join("original.deckcraft");
    let pptx = scratch.0.join("converted.pptx");
    let restored = scratch.0.join("restored.deckcraft");

    let result = Command::new(binary())
        .args(["run", "--cmd", r#"slide.new={"layout":"titleAndContent","title":"CLI roundtrip marker","body":"Owned synthetic text"}"#, "--save"])
        .arg(&native)
        .output()
        .expect("create synthetic presentation");
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));

    let expected = successful_json(&Command::new(binary()).arg("info").arg(&native).output().expect("inspect native"));
    assert_eq!(expected["slides"].as_array().map(Vec::len), Some(2));
    assert_eq!(expected["slides"][1]["title"], "CLI roundtrip marker");

    for (input, output) in [(&native, &pptx), (&pptx, &restored)] {
        let convert = Command::new(binary()).arg("convert").arg(input).arg(output).output().expect("convert presentation");
        assert!(convert.status.success(), "{}", String::from_utf8_lossy(&convert.stderr));
        assert!(std::fs::metadata(output).expect("converted artifact").len() > 0);
    }

    let observed = successful_json(&Command::new(binary()).arg("info").arg(&restored).output().expect("inspect restored deck"));
    assert_eq!(observed["slides"].as_array().map(Vec::len), Some(2));
    assert_eq!(observed["slides"][1]["title"], "CLI roundtrip marker");
    assert_eq!(observed["slideSize"], expected["slideSize"]);
}

#[test]
fn executable_rejects_corrupt_input_and_invalid_commands() {
    let scratch = Scratch::new();
    let broken = scratch.0.join("corrupt.deckcraft");
    let output = scratch.0.join("should-not-exist.deckcraft");
    std::fs::write(&broken, b"PK\\x03\\x04broken".as_slice()).expect("write synthetic corruption");
    let info = Command::new(binary()).arg("info").arg(&broken).output().expect("open corrupt deck");
    assert!(!info.status.success(), "corrupt input must not be reported as a valid presentation");

    let invalid =
        Command::new(binary()).args(["run", "--cmd", "a.command.that.does.not.exist", "--save"]).arg(&output).output().expect("run invalid command");
    assert!(!invalid.status.success());
    assert!(!output.exists(), "failed command must not save a partial deck");
    assert!(String::from_utf8_lossy(&invalid.stderr).contains("a.command.that.does.not.exist"));
}

#[test]
fn executable_mcp_stdio_exchanges_jsonrpc_and_terminates_on_eof() {
    let mut child =
        Command::new(binary()).arg("mcp").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().expect("spawn MCP server");
    let requests = concat!(
        r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18"}}"#,
        "\n",
        r#"{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}"#,
        "\n",
        r#"{"jsonrpc":"2.0","id":3,"method":"no.such.method","params":{}}"#,
        "\n"
    );
    child.stdin.take().expect("stdin pipe").write_all(requests.as_bytes()).expect("write protocol requests");
    let output = child.wait_with_output().expect("MCP server should finish at EOF");
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let messages: Vec<serde_json::Value> = String::from_utf8(output.stdout)
        .expect("UTF-8 JSON-RPC")
        .lines()
        .map(|line| serde_json::from_str(line).expect("valid JSON-RPC reply"))
        .collect();
    assert_eq!(messages.len(), 3);
    assert_eq!(messages[0]["id"], 1);
    assert_eq!(messages[0]["result"]["serverInfo"]["name"], "deckcraft");
    assert_eq!(messages[1]["id"], 2);
    assert!(messages[1]["result"]["tools"].as_array().is_some_and(|tools| !tools.is_empty()));
    assert_eq!(messages[2]["id"], 3);
    assert_eq!(messages[2]["error"]["code"], -32601);
}
